/* Supplied panel brand artwork. The one native WebP is retained; the original
   PNG logos remain lossless until a dedicated image optimiser is used at build time. */
(()=>{
  const extensions={
    '8k-strong':'webp','trex-iptv':'png','lion-ott':'png','promax-4k-ott':'png',
    'crystal-ott':'png','dream-4k-iptv':'png','mega-ott':'png','dino-iptv':'png',
    'nexon-iptv':'png','magnum-golden-ott':'png','tivione':'png','ultra-8k-ott':'png',
    'infinity-iptv':'png','eagle-iptv':'png','max-ott':'png'
  };
  const asset=slug=>`/assets/logos/${slug}.${extensions[slug]||'png'}`;
  function image(slug,name,cls){const img=document.createElement('img');img.className=cls;img.src=asset(slug);img.alt=`${name} logo`;img.loading='lazy';return img}
  function apply(){
    document.head.insertAdjacentHTML('beforeend','<style>.product-logo{overflow:hidden;padding:3px}.product-logo img{display:block;width:100%;height:100%;object-fit:contain}.panelhero-brand{width:min(210px,48vw);height:82px;object-fit:contain;object-position:left center;margin:0 0 18px;display:block}.server-slide-mark{overflow:hidden;padding:12px;background:#fff!important}.server-slide-mark img{width:100%;height:100%;object-fit:contain;display:block}@media(max-width:700px){.panelhero-brand{height:58px}.server-slide-mark{padding:6px}}</style>');
    document.querySelectorAll('.panel').forEach(card=>{
      const href=card.querySelector('a[href*="/panels/"]')?.getAttribute('href')||'';
      const slug=href.split('/').filter(Boolean).pop();
      const p=(window.panels||[]).find(x=>x[0]===slug); const mark=card.querySelector('.panel-mark,.product-logo');
      if(p&&mark&&extensions[slug]){mark.className='product-logo';mark.replaceChildren(image(slug,p[1],'panel-logo-image'))}
    });
    const path=location.pathname.replace(/\/$/,''); const p=(window.panels||[]).find(x=>path===`/panels/${x[0]}`);
    if(p&&extensions[p[0]]&&!document.querySelector('.panelhero-brand')) document.querySelector('.panelhero .wrap')?.insertBefore(image(p[0],p[1],'panelhero-brand'),document.querySelector('.panelhero .wrap').firstChild);
    document.querySelectorAll('.server-slide').forEach(slide=>{
      const title=slide.querySelector('h2')?.textContent; const p=(window.panels||[]).find(x=>x[1]===title);const mark=slide.querySelector('.server-slide-mark');
      if(p&&mark&&extensions[p[0]]) mark.replaceChildren(image(p[0],p[1],'slide-logo-image'));
    });
  }
  setTimeout(apply,250);
})();
